{
    "type": "function",
    "function": {
        "name": "freeze_account",
        "description": "계좌 거래를 일시 중지하여 계좌가 의심될 때 동결 처리 절차를 실행한다. 계좌 식별자, 동결 이유, 동결 날짜, 동결 상태를 기록한다.",
        "parameters": {
            "type": "object",
            "properties": {
                "account_id": {
                    "type": "integer",
                    "description": "동결될 계좌번호(sender_acc 또는 receiver_acc)"
                },
                "reason": {
                    "type": "string",
                    "description": "동결의 이유(예: 의심된 거래, AML/CTF 규정 준수)"
                },
                "effective_date": {
                    "type": "integer",
                    "description": "동결의 효력 시작일(YYYYMMDD 정수)"
                },
                "status": {
                    "type": "string",
                    "description": "동결 상태(기본ly 'active', 'frozen'로 변경)"
                }
            },
            "required": [
                "account_id",
                "reason",
                "effective_date"
            ]
        }
    }
    },
    {
    "type": "function",
