                        "type": "integer",
                        "description": "시작 계좌(shortest_path에 필수)"
                    },
                    "account_b": {
                        "type": "integer",
                        "description": "도착 계좌(shortest_path에 필수)"
                    },
                    "min_len": {
                        "type": "integer",
                        "description": "최소 순환 길이(기본 3)",
                        "default": 3
                    },
                    "max_len": {
                        "type": "integer",
                        "description": "최대 순환 길이(기본 6)",
                        "default": 6
                    },
                    "min_layers": {
                        "type": "integer",
                        "description": "최소 레이어링 단계 수(기본 3)",
                        "default": 3
                    },
                    "min_inflow": {
                        "type": "integer",
                        "description": "funnel: funnel 계좌가 자금을 받는 서로 다른 계좌의 최소 수(기본 5)",
                        "default": 5
                    },
                    "max_outflow": {
                        "type": "integer",
                        "description": "funnel: funnel 계좌가 자금을 내보내는 서로 다른 계좌의 최대 수. 내보내는 거래상대가 최소 한 곳은 있어야 한다(기본 5)",
                        "default": 5
                    },
                    "limit": {
                        "type": "integer",
                        "description": "반환할 최대 결과 수(기본 20)",
                        "default": 20
                    }
                },
                "required": [
                    "pattern_type"
                ]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "detect_dormant_reactivation",
            "description": "오랜 휴면 뒤 재활성화된 계좌를 탐지한다: dormant_days(기본 180일) 동안 거래가 없다가 min_reactivation_amount 이상인 거래가 발생한 경우. 마지막 활동일, 재활성화일, 휴면 기간의 길이, 재활성화 당일의 거래 건수와 금액을 반환한다.",
            "parameters": {
                "type": "object",
                "properties": {
                    "dormant_days": {
                        "type": "integer",
                        "description": "휴면 판정 기준 일수(기본 180)",
                        "default": 180
                    },
                    "min_reactivation_amount": {
                        "type": "integer",
                        "description": "재활성화로 볼 최소 거래금액(기본 500만원)",
                        "default": 5000000
                    },
                    "limit": {
                        "type": "integer",
                        "description": "최대 결과 수(기본 20)",
                        "default": 20
                    }
                },
                "required": []
            }
        }
    },
    {
        "type": "function",
